import 'package:flutter/material.dart';import '../../Features/Authentication/presentation/pages/authentication_screen.dart';import '../../Features/Boarding/presentation/pages/boarding_screen.dart';import '../../Features/Cart/presentation/pages/cart_screen.dart';import '../../Features/Main/presentation/pages/main_screen.dart';import '../../Features/Research/presentation/pages/search_screen.dart';import '../../Features/Splash/Pages/splash_screen.dart';import 'route_name.dart';class AppRouteBuilders {  static final Map<String, WidgetBuilder> routeBuilders = {    AppRoutes.splash: (_) => const SplashScreen(),    AppRoutes.boarding: (_) => const BoardingScreen(),    AppRoutes.authentication: (_) => const AuthenticationScreen(),    AppRoutes.main: (_) => const MainScreen(),    AppRoutes.search: (_) => const SearchScreen(),    AppRoutes.cart: (_) => const CartScreen(),  };  static Route<dynamic> generateRoute(RouteSettings settings) {    final builder = routeBuilders[settings.name];    if (builder != null) {      return MaterialPageRoute(builder: builder);    }    return MaterialPageRoute(      builder: (_) => Scaffold(        body: Center(          child:              Text('No route defined for "${settings.name?.split("/").last}" '),        ),      ),    );  }}